def is_nested(string):
    def dfs(index, depth):
        if index >= len(string):
            return depth == 0  # If we've reached the end of the string and have a non-zero depth, it's invalid

        # Move to the next character
        if string[index] == '[':
            depth += 1
        elif string[index] == ']':
            depth -= 1

        # If depth is negative, it means there's a closing bracket without a matching opening bracket
        if depth < 0:
            return False

        # If we have a valid subsequence, return True
        if depth == 0:
            return True

        # Recursively check the next character
        return dfs(index + 1, depth)

    return dfs(0, 0)

