def match_parens(lst):
    open_count = 0
    close_count = 0

    # Iterate through the list of strings
    for s in lst:
        # Iterate through each character in the string
        for char in s:
            if char == '(':
                open_count += 1
            elif char == ')':
                close_count += 1

            # Check if closing parentheses outnumber opening ones
            if close_count > open_count:
                return 'No'

    # Check if we have reached a state where open_count is zero
    if open_count == 0:
        return 'Yes'

    return 'No'

