        for char in s:
            if char == '(':
                balance += 1
            elif char == ')':
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    # Check both possible concatenations
    if is_balanced(lst[0] + lst[1]):
        return 'Yes'
    elif is_balanced(lst[1] + lst[0]):
        return 'Yes'
    else:
        return 'No'

