    """
    try:
        # Attempt to convert the date string to a datetime object
        datetime.strptime(date, '%m-%d-%Y')
        # Check if the year is a leap year for February
        if datetime.date(int(date.split('-')[2]), int(date.split('-')[0]), 2).strftime('%B') == 'February':
