def prime_intersection_length(interval1, interval2):
    """Determine if the length of the intersection is a prime number."""
    if not intersection(interval1, interval2):
        return "NO"

    intersection_start, intersection_end = intersection(interval1, interval2)
    intersection_length = intersection_end - intersection_start + 1

    if is_prime(intersection_length):
        return "YES"
    else:
        return "NO"

