def encode_shift(s: str):
    """
    returns encoded string by shifting every character by 5 in the alphabet.
    """
    shifted_string = []
    for char in s:
        if char in string.ascii_lowercase:
            # Calculate new character by shifting 5 places forward
            shifted_char = chr(((ord(char) - ord('a') + 5) % 26) + ord('a'))
            shifted_string.append(shifted_char)
        elif char in string.ascii_uppercase:
            # Calculate new character by shifting 5 places forward, preserving case
            shifted_char = chr(((ord(char) - ord('A') + 5) % 26) + ord('A'))
            shifted_string.append(shifted_char)
        else:
            # Non-alphabetic characters are added unchanged
            shifted_string.append(char)
    return ''.join(shifted_string)


