    """
    Write a function count_nums which takes an array of integers and returns
    the number of elements which has a sum of digits > 0.
    If a number is negative, then its first signed digit will be negative:
    e.g. -123 has signed digits -1, 2, and 3.
    >>> count_nums([]) == 0
    >>> count_nums([-1, 11, -11]) == 1
    >>> count_nums([1, 1, 2]) == 3
    """
    def sum_of_digits(n):
        # Convert the number to a string and iterate over each character
        str_n = str(n)
        # Handle negative numbers
        if str_n[0] == '-':
            # Add the negative sign to the first digit and sum the rest
            return int('-' + str_n[1]) + sum(int(digit) for digit in str_n[2:])
        else:
            # Sum the digits directly
            return sum(int(digit) for digit in str_n)

    # Count numbers with a sum of digits greater than zero
    count = 0
    for num in arr:
        if sum_of_digits(num) > 0:
            count += 1

    return count

