def match_parens(lst):
    # Extract the two strings from the list
    str1, str2 = lst

    # Count the total number of '(' and ')' in both strings
    open_count = str1.count('(') + str2.count('(')
    close_count = str1.count(')') + str2.count(')')

    # If the counts are not equal, return 'No'
    if open_count != close_count:
        return 'No'

    # Check if we can concatenate in any order to form a balanced string
    def is_balanced(s):
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            # If balance goes negative, it means there are more ')' than '('
            if balance < 0:
                return False
        return balance == 0

    # Check both possible concatenations
    if is_balanced(str1 + str2) or is_balanced(str2 + str1):
        return 'Yes'
    else:
        return 'No'

