def match_parens(lst):
    # Try concatenating in both possible orders
    for order in [lst, lst[::-1]]:
        # Count the number of open and close parentheses
        open_count = 0
        close_count = 0
        for char in order:
            if char == '(':
                open_count += 1
            elif char == ')':
                close_count += 1
        # Check if the number of open and close parentheses is equal
        if open_count == close_count:
            return 'Yes'
