    for s in [lst[0] + lst[1], lst[1] + lst[0]]:
        # Initialize counter for open parentheses
        balance = 0
        # Iterate over each character in the string
        for char in s:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            # If at any point the balance goes negative, the parentheses are not balanced
            if balance < 0:
                break
        # If we finish iterating over the string and balance is zero, the parentheses are balanced
        if balance == 0:
            return 'Yes'
