            if char == '(':
                balance += 1
            else:  # char == ')'
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    s1, s2 = lst
    # Check both concatenation orders
    if is_balanced(s1 + s2) or is_balanced(s2 + s1):
        return 'Yes'
    else:
        return 'No'

