    # List of planets in order from closest to farthest from the Sun
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    # Check if both planet1 and planet2 are valid planet names
    if planet1 not in planets or planet2 not in planets:
        return ()

    # Get the indices of the planets
    index1 = planets.index(planet1)
    index2 = planets.index(planet2)

    # If index1 is greater than index2, swap them
    if index1 > index2:
        index1, index2 = index2, index1

    # Get the planets between the two indices
    result = tuple(planets[index1 + 1:index2])

    return result

