def is_prime(n):
    """Helper function to check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def intersection(interval1, interval2):
    a, b = interval1
    c, d = interval2

    # Calculate the intersection interval
    start = max(a, c)
    end = min(b, d)

    # Calculate the length of the intersection
    if start > end:
        length = 0
    else:
        length = end - start + 1

    # Check if the length is a prime number
    if is_prime(length):
        return "YES"
    else:
        return "NO"

